  "Button does nothing? Choose <b>Copy setup instead</b> and paste it into <code>~/.cursor/mcp.json</code> (create the file when missing).": "Händer inget med knappen? Välj <b>Kopiera inställningen i stället</b> och klistra in den i <code>~/.cursor/mcp.json</code> (skapa filen om den saknas).",
  "Button does nothing? Choose <b>Copy setup instead</b>, run <b>MCP: Open User Configuration</b> from the Command Palette and paste it there. VS Code uses <code>servers</code>, not <code>mcpServers</code>.": "Händer inget med knappen? Välj <b>Kopiera inställningen i stället</b>, kör <b>MCP: Open User Configuration</b> från kommandopaletten och klistra in den där. VS Code använder <code>servers</code>, inte <code>mcpServers</code>.",
