  "Chat with a model you choose; {mnemo} reads, writes, tags, links, moves and tidies notes with Memora's own tools. It cannot browse the web, run commands, delete for good or change the server. Keys are sealed on this server and never sent to the browser.": "Chatta med en modell du väljer; {mnemo} läser, skriver, taggar, länkar, flyttar och städar anteckningar med Memoras egna verktyg. Den kan inte surfa på webben, köra kommandon, radera för gott eller ändra servern. Nycklar förseglas på den här servern och skickas aldrig till webbläsaren.",
