  "Claude and ChatGPT sign in with your Memora account. Nothing to copy.": "Claude och ChatGPT loggar in med ditt Memora-konto. Inget att kopiera.",
  "Claude models": "Claude-modeller",
  "Claude signs in over OAuth, so no key is pasted: it gets its own key when you press Allow. Without sign-in, connect it as <b>Other app</b> and send the header <code>Authorization: Bearer &lt;key&gt;</code>.": "Claude loggar in via OAuth, så ingen nyckel klistras in: den får en egen nyckel när du trycker på Tillåt. Utan inloggning kopplar du den som <b>Annan app</b> och skickar rubriken <code>Authorization: Bearer &lt;key&gt;</code>.",
  "Claude, ChatGPT, Cursor and more": "Claude, ChatGPT, Cursor och fler",
  "Claude, ChatGPT, Cursor and more, each with its own key": "Claude, ChatGPT, Cursor och fler, var och en med sin egen nyckel",
  "Claude, ChatGPT, Cursor, Codex and others each get their own access, so you can see what each one does.": "Claude, ChatGPT, Cursor, Codex och andra får var sin åtkomst, så att du kan se vad var och en gör.",
  "Claude, Cursor, ChatGPT and your own agent share one Memora, reachable from this computer, the local network or the internet": "Claude, Cursor, ChatGPT och din egen agent delar en Memora, nåbar från den här datorn, det lokala nätverket eller internet",
