  "Deleted chats and their messages are gone for good. Your notes are not touched, and a chat that is answering right now is left alone.": "Borttagna chattar och deras meddelanden är borta för gott. Dina anteckningar berörs inte, och en chatt som svarar just nu lämnas ifred.",
  "Deleted notes": "Borttagna anteckningar",
  "Deleted notes wait here until you restore them or delete them forever. When you restore, you choose where the note goes: its old folder, another folder or the top level.": "Borttagna anteckningar väntar här tills du återställer dem eller tar bort dem för gott. När du återställer väljer du var anteckningen hamnar: i sin gamla mapp, en annan mapp eller på toppnivå.",
