  "Drag a card into another folder frame to move the note on disk. Drag a frame by its name to rearrange the board; drop it onto another frame to move the whole folder there. Double-click a title to rename. On touch: drag to pan, pinch to zoom, long-press a card to move it, tap to preview.": "Dra ett kort till en annan mappram för att flytta anteckningen på disken. Dra en ram i namnet för att ordna om tavlan; släpp den på en annan ram för att flytta hela mappen dit. Dubbelklicka på en titel för att byta namn. På pekskärm: dra för att panorera, nyp för att zooma, tryck länge på ett kort för att flytta det, tryck för att förhandsgranska.",
  "Drag a note here to pin it": "Dra en anteckning hit för att fästa den",
  "Drag notes or folders here to pin them": "Dra anteckningar eller mappar hit för att fästa dem",
  "Drag notes or folders onto a folder to move them, onto Pinned to pin them.": "Dra anteckningar eller mappar till en mapp för att flytta dem, till Fästa för att fästa dem.",
  "Drag notes · double-click to pin · / search · #tag finds tags · F fit · 1 2 3 layouts": "Dra anteckningar · dubbelklicka för att fästa · / sök · #tagg hittar taggar · F anpassa · 1 2 3 layouter",
  "Drag to move the folder frame; double-click to rename": "Dra för att flytta mappramen; dubbelklicka för att byta namn",
  "Drag to resize · double-click to reset": "Dra för att ändra storlek · dubbelklicka för att återställa",
  "Drag to turn · scroll to zoom · click a point to open its note": "Dra för att vrida · scrolla för att zooma · klicka på en punkt för att öppna dess anteckning",
  "Drag to turn · scroll to zoom · click a point to open its note · / to search · #tag finds tags": "Dra för att vrida · scrolla för att zooma · klicka på en punkt för att öppna dess anteckning · / för att söka · #tagg hittar taggar",
  "Draw a chart of how many notes I write each week": "Rita ett diagram över hur många anteckningar jag skriver varje vecka",
