  "Dyslexic": "Dyslexi",
  "Each AI app connects over MCP with its own key and permissions.": "Varje AI-app ansluter via MCP med sin egen nyckel och sina egna behörigheter.",
  "Each AI app you connect is an agent with its own key, so you see what each one does and can turn one off on its own.": "Varje AI-app du ansluter är en agent med en egen nyckel, så du ser vad var och en gör och kan stänga av en för sig.",
  "Each agent": "Varje agent",
  "Each agent belongs to one app. For another app or device, make a new agent.": "Varje agent hör till en app. För en annan app eller enhet, skapa en ny agent.",
  "Each agent belongs to one app. To use Memora in another app, create a separate agent for it.": "Varje agent hör till en app. Om du vill använda Memora i en annan app, skapa en separat agent för den.",
  "Each app gets its own key": "Varje app får sin egen nyckel",
  "Each has a short id that never changes, so names can change freely. Mnemo sets them up, changes their instructions or model, messages, waits for, stops, finishes and removes them, one or all at once, and can let them work in the background. Each card shows Instruction, Activity and Answer.": "Var och en har ett kort id som aldrig ändras, så namn kan bytas fritt. Mnemo sätter upp dem, ändrar deras instruktioner eller modell, skickar meddelanden, väntar på, stoppar, avslutar och tar bort dem, en i taget eller alla på en gång, och kan låta dem arbeta i bakgrunden. Varje kort visar Instruktion, Aktivitet och Svar.",
  "Each kind is measured against its own room: its limit when set, else what it uses plus the free disk space{disk}. Empty limit: none.": "Varje sort mäts mot sitt eget utrymme: dess gräns om den är satt, annars det den använder plus det lediga diskutrymmet{disk}. Tom gräns: ingen.",
  "Each one gets its own key from Memora.": "Var och en får sin egen nyckel från Memora.",
