  "Error 404": "Fel 404",
  "Even in daily use, a browser signs in again after this long. It cannot be shorter than the inactivity time.": "Även vid daglig användning loggar en webbläsare in igen efter så här lång tid. Den kan inte vara kortare än inaktivitetstiden.",
  "Every AI loses {n} tool at once. Asks first.": "Varje AI förlorar {n} verktyg samtidigt. Frågar först.",
  "Every AI loses {n} tools at once. Asks first.": "Varje AI förlorar {n} verktyg samtidigt. Frågar först.",
  "Every action, newest first": "Varje åtgärd, senaste först",
  "Every action, newest first, with search and filters.": "Varje åtgärd, senaste först, med sökning och filter.",
  "Every address from one to another.": "Varje adress från en till en annan.",
  "Every address from the first to the last, joined by a dash.": "Varje adress från den första till den sista, förenade med ett streck.",
  "Every agent usually starts from zero. {bold} connect each agent once and they all read the same vault and write back to it, so what one learns, the others can use.": "Varje agent börjar oftast från noll. {bold} anslut varje agent en gång så läser alla samma valv och skriver tillbaka till det, så att det en lär sig kan de andra använda.",
  "Every browser and agent is disconnected until someone starts Memora again on that machine. This page cannot start it again.": "Alla webbläsare och agenter kopplas från tills någon startar Memora igen på den datorn. Den här sidan kan inte starta den igen.",
  "Every call shows up live in the brain and Activity": "Varje anrop visas live i hjärnan och Aktivitet",
  "Every change Mnemo makes shows in Activity and can be undone from History.": "Varje ändring Mnemo gör visas i Aktivitet och kan ångras från Historik.",
  "Every change, by you or an app, shows in Activity and can be undone from History.": "Varje ändring, av dig eller en app, visas i Aktivitet och kan ångras från Historik.",
  "Every chat is archived.": "Alla chattar är arkiverade.",
  "Every chat with your notes agent": "Varje chatt med din anteckningsagent",
  "Every connected AI loses all {n} tools at once and can no longer read or change your notes until you turn tools back on here.": "Varje ansluten AI förlorar alla {n} verktyg samtidigt och kan inte längre läsa eller ändra dina anteckningar förrän du slår på verktygen igen här.",
  "Every connected AI loses it at once. You can turn it back on any time.": "Varje ansluten AI förlorar det samtidigt. Du kan slå på det igen när som helst.",
  "Every connected AI loses them at once. You can turn them back on any time.": "Varje ansluten AI förlorar dem samtidigt. Du kan slå på dem igen när som helst.",
  "Every connected agent loses its memory until Memora runs again.": "Varje ansluten agent förlorar sitt minne tills Memora körs igen.",
  "Every device on a home or office network, written as address/size: 192.168.1.0/24 covers 192.168.1.0 to 192.168.1.255.": "Varje enhet i ett hem- eller kontorsnätverk, skrivet som adress/storlek: 192.168.1.0/24 omfattar 192.168.1.0 till 192.168.1.255.",
  "Every device on a home or office network.": "Varje enhet i ett hem- eller kontorsnätverk.",
  "Every image in the notes folder and where it is shown, and the pictures kept for Mnemo chats.": "Varje bild i anteckningsmappen och var den visas, plus bilderna som sparas för Mnemo-chattar.",
  "Every image is used in a note.": "Varje bild används i en anteckning.",
  "Every note": "Varje anteckning",
  "Every note and link, in 3D, as a graph or on a board.": "Varje anteckning och länk, i 3D, som graf eller på en tavla.",
  "Every note and subfolder in \"{path}\" moves into {folder}; \"{name}\" is then removed. If a name is already taken there, a number is added to it.": "Varje anteckning och undermapp i ”{path}” flyttas till {folder}; ”{name}” tas sedan bort. Om ett namn redan är upptaget där läggs ett nummer till.",
  "Every note becomes a card here, inside a frame for its folder. The guide shows how to have an AI save its knowledge here, or write a note yourself.": "Varje anteckning blir ett kort här, i en ram för sin mapp. Guiden visar hur du låter en AI spara sin kunskap här, eller skriver en anteckning själv.",
  "Every note becomes a point of light here, grouped by folder. The guide shows how to have an AI save its knowledge here, or write a note yourself.": "Varje anteckning blir en ljuspunkt här, grupperad efter mapp. Guiden visar hur du låter en AI spara sin kunskap här, eller skriver en anteckning själv.",
  "Every note tagged #{tag} ({notes}) gets the new name, inline #tags in the text too.": "Varje anteckning med taggen #{tag} ({notes}) får det nya namnet, inbäddade #taggar i texten också.",
  "Every note tagged {tags} gets one tag instead ({notes}). Inline #tags in the text change too. There is no one-step undo; each note keeps its history.": "Varje anteckning med {tags} får en tagg i stället ({notes}). Inbäddade #taggar i texten ändras också. Det går inte att ångra i ett steg; varje anteckning behåller sin historik.",
  "Every read and write by an agent shows up live, so you always know who did what.": "Varje läsning och skrivning av en agent visas live, så du vet alltid vem som gjorde vad.",
  "Every request that reaches this rule is {verb}.": "Varje förfrågan som når den här regeln {verb}.",
  "Every request. Put it last, to catch whatever the rules above did not.": "Varje förfrågan. Lägg den sist för att fånga det reglerna ovan inte tog.",
  "Every setting and where it lives.": "Varje inställning och var den finns.",
  "Every shortcut in the web UI.": "Alla genvägar i webbgränssnittet.",
  "Every tag and its notes": "Varje tagg och dess anteckningar",
