  "Follow links between notes: neighbours, paths, hubs and loose ends.": "Följ länkar mellan anteckningar: grannar, vägar, nav och lösa trådar.",
  "Follow the {app} setup guide to connect it.": "Följ installationsguiden för {app} för att ansluta den.",
