  "For": "För",
  "For authentication choose <b>OAuth</b>, leave the client ID and secret empty, and click <b>Create</b>. A Memora page opens: press <b>Allow</b>.": "Välj <b>OAuth</b> som autentisering, lämna klient-ID och hemlighet tomma och klicka på <b>Skapa</b>. En Memora-sida öppnas: tryck på <b>Tillåt</b>.",
