  "From anywhere": "Från var som helst",
  "From now on, whenever I tell you something important, save it into Memora. Try it now: save a note that I started using Memora today.": "Från och med nu, när jag berättar något viktigt, spara det i Memora. Testa nu: spara en anteckning om att jag började använda Memora i dag.",
