  "Gathered to-dos": "Samlade att göra",
  "Gathering the real activity for {range}. This can take a moment on a big log, please wait.": "Samlar den verkliga aktiviteten för {range}. Det kan ta en stund med en stor logg, vänta.",
  "General": "Allmänt",
  "Get a one-time code on the server": "Hämta en engångskod på servern",
  "Get started": "Kom igång",
  "Get to know me from my notes. Look through my vault (recent notes, journals, projects, anything about me) and keep what you learn with remember_owner: who I am, what I work on, how I like answers, what I like. Short, lasting things only, never secrets. Then tell me in a few lines what you kept.": "Lär känna mig genom mina anteckningar. Gå igenom mitt valv (senaste anteckningar, dagböcker, projekt, allt om mig) och spara det du lär dig med remember_owner: vem jag är, vad jag arbetar med, hur jag vill ha svar, vad jag gillar. Bara korta, bestående saker, aldrig hemligheter. Berätta sedan i några rader vad du sparade.",
  "Gets its own agent key: read and write nodes over MCP": "Får en egen agentnyckel: läsa och skriva noder via MCP",
  "Getting started": "Komma igång",
  "GitHub answered HTTP {code}": "GitHub svarade med HTTP {code}",
  "Give Claude, Cursor or any MCP app its own key, then let it save what it already knows about you.": "Ge Claude, Cursor eller någon MCP-app en egen nyckel och låt den sedan spara det den redan vet om dig.",
  "Give a key read-only access, or let it write too.": "Ge en nyckel skrivskyddad åtkomst, eller låt den skriva också.",
  "Give each app or device its own agent. Activity then shows exactly who did what, and you can turn one off without touching the others.": "Ge varje app eller enhet en egen agent. Aktivitet visar då exakt vem som gjorde vad, och du kan stänga av en utan att röra de andra.",
  "Give it a name you recognise": "Ge den ett namn du känner igen",
  "Give the agent a name": "Ge agenten ett namn",
  "Give the provider a name": "Ge leverantören ett namn",
  "Give the tag a name: letters, digits and - _ / . only.": "Ge taggen ett namn: bara bokstäver, siffror och - _ / .",
