  "How Memora looks for you. Saved in this browser only.": "Hur Memora ser ut för dig. Sparas bara i den här webbläsaren.",
  "How far apart the folder islands of the Clusters layout are.": "Hur långt isär mapparnas öar ligger i layouten Kluster.",
  "How far apart the rings of the Radial layout are.": "Hur långt isär ringarna ligger i layouten Radiell.",
  "How full notes, images and chats are, and their limits": "Hur fulla anteckningar, bilder och chattar är, och deras gränser",
  "How hard notes push each other apart in the Force layout.": "Hur hårt anteckningar stöter bort varandra i layouten Kraft.",
  "How it works": "Så fungerar det",
  "How large an image may be, and what images take": "Hur stor en bild får vara och vad bilder tar",
  "How many notes": "Hur många anteckningar",
  "How much history the server keeps": "Hur mycket historik servern sparar",
  "How much room notes, images and Mnemo chats take, each against its own room. A banner warns when one is almost full.": "Hur mycket utrymme anteckningar, bilder och Mnemo-chattar tar, var och en mot sitt eget utrymme. En banderoll varnar när något nästan är fullt.",
  "How the agent itself shows up: its display name and colour.": "Hur agenten själv visas: dess visningsnamn och färg.",
  "How to update": "Så uppdaterar du",
  "How {mnemo} works": "Så fungerar {mnemo}",
  "Humanist": "Humanist",
  "I find, read, write, tag, link and tidy your notes. No web, no shell: only your vault.": "Jag hittar, läser, skriver, taggar, länkar och städar dina anteckningar. Ingen webb, inget skal: bara ditt valv.",
  "Icon": "Ikon",
  "Icon {name}": "Ikon {name}",
  "Identity": "Identitet",
  "Idle": "Inaktiv",
  "If it's been useful to you, a star on GitHub or telling a friend helps others find it. No worries if not.": "Om den har varit till nytta hjälper en stjärna på GitHub eller ett ord till en vän andra att hitta den. Ingen fara om inte.",
  "If you leave, they are kept on this device and offered again when you open the note.": "Om du lämnar sparas de på den här enheten och erbjuds igen när du öppnar anteckningen.",
  "Image": "Bild",
  "Image (or paste or drop one)": "Bild (eller klistra in eller släpp en)",
  "Image deleted": "Bilden togs bort",
  "Image line copied": "Bildraden kopierades",
  "Image you attached": "Bild du bifogade",
  "Image {name}": "Bild {name}",
  "Images": "Bilder",
  "Images can now be up to {n} MB": "Bilder kan nu vara upp till {n} MB",
  "Images in this folder": "Bilder i den här mappen",
  "Images live beside the notes that show them. Choose how large one may be, and see what notes and images take.": "Bilder ligger bredvid anteckningarna som visar dem. Välj hur stor en får vara och se vad anteckningar och bilder tar.",
  "Import and export": "Import och export",
  "Imported": "Importerad",
  "In ChatGPT, open <b>Settings → Apps &amp; Connectors → Advanced settings</b> and turn on <b>Developer mode</b>. Then choose <b>Create</b>.": "Öppna <b>Settings → Apps &amp; Connectors → Advanced settings</b> i ChatGPT och slå på <b>Developer mode</b>. Välj sedan <b>Create</b>.",
  "In Claude (web or desktop), open <b>Settings → Connectors</b> and choose <b>Add custom connector</b>.": "Öppna <b>Settings → Connectors</b> i Claude (webb eller skrivbord) och välj <b>Add custom connector</b>.",
  "In Claude Desktop, open <b>Settings → Developer → Edit Config</b>. On newer versions, pick <b>Claude</b> instead.": "Öppna <b>Settings → Developer → Edit Config</b> i Claude Desktop. I nyare versioner väljer du <b>Claude</b> i stället.",
  "In Windsurf, open <b>Settings → Cascade → MCP servers</b> and choose <b>View raw config</b>.": "Öppna <b>Settings → Cascade → MCP servers</b> i Windsurf och välj <b>View raw config</b>.",
  "In note text": "I anteckningstext",
  "In notes": "I anteckningar",
  "In search: actions only (new note, theme ...)": "I sökningen: bara åtgärder (ny anteckning, tema ...)",
  "In short": "Kort sagt",
  "In the folder {folder}": "I mappen {folder}",
  "In this chat": "I den här chatten",
