  "Installed": "Installerad",
  "Installing, connecting agents, settings and reference.": "Installation, anslutning av agenter, inställningar och referens.",
  "Instance not ready": "Instansen är inte redo",
  "Instruction": "Instruktion",
  "Instruction style": "Instruktionsstil",
  "Instructions": "Instruktioner",
  "Instructions from {mnemo}": "Instruktioner från {mnemo}",
  "Interface": "Gränssnitt",
  "Internet (tunnel)": "Internet (tunnel)",
  "Internet address (IP)": "Internetadress (IP)",
  "It becomes your first rule.": "Den blir din första regel.",
  "It becomes {path}. Links to its notes keep working.": "Den blir {path}. Länkar till dess anteckningar fortsätter fungera.",
  "It can change notes, but nothing lets it connect.": "Den kan ändra anteckningar, men inget låter den ansluta.",
  "It can search and read your notes, but not change them": "Den kan söka i och läsa dina anteckningar, men inte ändra dem",
  "It can search, read and save your notes": "Den kan söka i, läsa och spara dina anteckningar",
  "It can {list}.": "Den kan {list}.",
  "It cannot do anything yet": "Den kan inte göra något än",
  "It has full control: it reads and changes notes, and can manage Memora and other agents": "Den har full kontroll: den läser och ändrar anteckningar och kan hantera Memora och andra agenter",
  "It holds {n} note. Next you choose what happens to them: move them to another folder, or move them to the Trash. Nothing is changed yet.": "Den innehåller {n} anteckning. Härnäst väljer du vad som händer med dem: flytta dem till en annan mapp eller till Papperskorgen. Inget har ändrats än.",
  "It holds {n} notes. Next you choose what happens to them: move them to another folder, or move them to the Trash. Nothing is changed yet.": "Den innehåller {n} anteckningar. Härnäst väljer du vad som händer med dem: flytta dem till en annan mapp eller till Papperskorgen. Inget har ändrats än.",
  "It is added at the end, as rule {n}, so it is checked last.": "Den läggs till sist, som regel {n}, så den kontrolleras sist.",
  "It is gone when you leave, pictures included. Changes to your notes still show in Activity and History.": "Allt försvinner när du lämnar, även bilder. Ändringar i dina anteckningar syns fortfarande i Aktivitet och Historik.",
  "It is kept locked on the server. Enter your Memora password and the buttons below put it in for you.": "Den hålls låst på servern. Ange ditt Memora-lösenord så lägger knapparna nedan in den åt dig.",
  "It is taking a while. Check the server, then reload this page.": "Det tar en stund. Kontrollera servern och ladda sedan om sidan.",
  "It leaves the Pinned list only; the folder itself stays where it is.": "Den lämnar bara listan Fästa; själva mappen stannar där den är.",
  "It leaves the Pinned list only; the note itself stays where it is.": "Den lämnar bara listan Fästa; själva anteckningen stannar där den är.",
  "It may have been renamed, moved or deleted. Deleted notes wait in the Trash.": "Den kan ha bytt namn, flyttats eller tagits bort. Borttagna anteckningar väntar i Papperskorgen.",
  "It moves; links to it are updated and pins follow.": "Den flyttas; länkar till den uppdateras och fästen följer med.",
  "It must sign in again and is told why": "Den måste logga in igen och får veta varför",
  "It prints a one-time code. This page moves on by itself.": "Den skriver ut en engångskod. Den här sidan går vidare av sig själv.",
  "It reached Memora but did not finish. It often works on the next try.": "Den nådde Memora men blev inte klar. Det fungerar ofta vid nästa försök.",
  "It reached Memora but did not finish: {error} It often works on the next try.": "Den nådde Memora men blev inte klar: {error} Det fungerar ofta vid nästa försök.",
  "It shows up under this name in Activity, the brain and the graph. Name it after the device when you use {app} in more than one place, like \"{example}\".": "Den visas under det här namnet i Aktivitet, hjärnan och grafen. Döp den efter enheten när du använder {app} på fler än ett ställe, som ”{example}”.",
  "It was shown when it was made. Make a new key to see one again.": "Den visades när den skapades. Skapa en ny nyckel för att se en igen.",
  "Italic": "Kursiv",
  "Its API key and its models are removed. Chats stay; a chat that used one of its models switches to the default.": "Dess API-nyckel och modeller tas bort. Chattar blir kvar; en chatt som använde en av dess modeller byter till standardmodellen.",
  "Its key and access stay the same in every notes folder. Connect another one any time.": "Dess nyckel och åtkomst är desamma i varje anteckningsmapp. Anslut en till när som helst.",
  "Its key is filled in on the next step": "Dess nyckel fylls i vid nästa steg",
  "Its key is refused until you turn it back on. Nothing is deleted.": "Dess nyckel nekas tills du slår på den igen. Inget tas bort.",
  "Its key is refused. Turn it on to let it connect again with the same key.": "Dess nyckel nekas. Slå på den så att den kan ansluta igen med samma nyckel.",
  "Its key stopped working. You can restore it until you reload the app.": "Dess nyckel slutade fungera. Du kan återställa den tills du laddar om appen.",
  "Its key stops working at once. Past activity stays; you can restore it until you reload the app.": "Dess nyckel slutar fungera direkt. Tidigare aktivitet finns kvar; du kan återställa den tills du laddar om appen.",
  "Its key was shown only once, when it was made. A new key replaces it and the old one stops working at once.": "Dess nyckel visades bara en gång, när den skapades. En ny nyckel ersätter den och den gamla slutar fungera direkt.",
  "Its notes are in its folders. You can also start one here.": "Dess anteckningar finns i dess mappar. Du kan också starta en här.",
  "Its numbers, timeline and export.": "Dess siffror, tidslinje och export.",
  "Its old folder is not known, so it goes to the top level": "Dess gamla mapp är okänd, så den hamnar på toppnivå",
  "Its page": "Dess sida",
  "Its page shows how to connect it.": "Dess sida visar hur du ansluter den.",
  "Its page: status, recent calls, access and settings.": "Dess sida: status, senaste anrop, åtkomst och inställningar.",
  "Its permissions are a custom mix. Pick a level to replace them, or fine-tune them under Advanced.": "Dess behörigheter är en egen blandning. Välj en nivå för att ersätta dem, eller finjustera under Avancerat.",
