  "Locks, mentions and assignments so agents do not overwrite each other.": "Lås, omnämnanden och tilldelningar så att agenter inte skriver över varandra.",
  "Long chats, light": "Långa chattar, lätta",
  "Long enough. A few more characters make it stronger.": "Tillräckligt långt. Några tecken till gör det starkare.",
  "Longer tasks show as a checklist above the message box: not started, in progress, done.": "Längre uppgifter visas som en checklista ovanför meddelanderutan: ej påbörjad, pågår, klar.",
  "Longest sign-in": "Längsta inloggning",
  "Longest sign-in must be at least the inactivity time": "Längsta inloggning måste vara minst lika lång som inaktivitetstiden",
  "Look for tags that mean the same thing": "Leta efter taggar som betyder samma sak",
  "Look through the project in this folder and save it into Memora: what it is for, how it is built, how to run it, technical decisions, and anything worth remembering. Make one note per topic, in a folder named after the project inside Projects.": "Gå igenom projektet i den här mappen och spara det i Memora: vad det är till för, hur det är byggt, hur man kör det, tekniska beslut och allt som är värt att minnas. Gör en anteckning per ämne, i en mapp med projektets namn inuti Projects.",
