  "Medium": "Medel",
  "Medium text": "Medelstor text",
  "Meet Mnemo, your notes agent": "Möt Mnemo, din anteckningsagent",
  "Memora address (MCP endpoint)": "Memora-adress (MCP-slutpunkt)",
  "Memora already uses this folder.": "Memora använder redan den här mappen.",
  "Memora by Codrihub Tech": "Memora av Codrihub Tech",
  "Memora can save notes here": "Memora kan spara anteckningar här",
  "Memora checks the folder and asks you to confirm before it switches. Nothing is moved or copied, and you can switch back here. Running in Docker? Use a folder mounted into the container.": "Memora kontrollerar mappen och ber dig bekräfta innan den byter. Inget flyttas eller kopieras, och du kan byta tillbaka här. Kör du Docker? Använd en mapp som är monterad i containern.",
  "Memora could not start.": "Memora kunde inte starta.",
  "Memora data folder": "Memoras datamapp",
  "Memora first checks that the new folder exists (or can be created) and that it can save notes there. If the check fails, nothing changes.": "Memora kontrollerar först att den nya mappen finns (eller kan skapas) och att den kan spara anteckningar där. Misslyckas kontrollen ändras ingenting.",
  "Memora first checks that the new folder exists and that it can save notes there. If the check fails, nothing changes.": "Memora kontrollerar först att den nya mappen finns och att den kan spara anteckningar där. Misslyckas kontrollen ändras ingenting.",
  "Memora in your language, Mnemo showing its plan as it works, and you choosing what it may use and see.": "Memora på ditt språk, Mnemo som visar sin plan medan den arbetar, och du som väljer vad den får använda och se.",
  "Memora is a notes app your AI apps can use too. You write in it, they read and write the same notes, and you can always see what changed.": "Memora är en anteckningsapp som även dina AI-appar kan använda. Du skriver i den, de läser och skriver samma anteckningar, och du kan alltid se vad som ändrats.",
  "Memora is free and open source": "Memora är gratis och öppen källkod",
  "Memora is free and open source. A star helps others find it.": "Memora är gratis och öppen källkod. En stjärna hjälper andra att hitta det.",
  "Memora is memory, advanced: built to remember what you and your AI learn, and to remember more the more you use it.": "Memora är minne, avancerat: byggt för att minnas vad du och din AI lär er, och minnas mer ju mer du använder det.",
  "Memora is restarting": "Memora startar om",
  "Memora is shut down": "Memora är avstängt",
  "Memora is still empty. Connect an AI app, send it one prompt, and it saves what it knows about you here, as notes you can read, edit and see in the brain.": "Memora är fortfarande tomt. Anslut en AI-app, skicka en prompt, så sparar den det den vet om dig här, som anteckningar du kan läsa, redigera och se i hjärnan.",
  "Memora keeps a list of your tags to suggest them while you type. Refresh it if a tag is missing or out of date.": "Memora håller en lista över dina taggar för att föreslå dem medan du skriver. Uppdatera den om en tagg saknas eller är föråldrad.",
  "Memora keeps every version of a note when the vault folder is a git repository. Run {cmd} in the vault folder once (see Configuration, “Version history” in the docs); from then on every change is kept here.": "Memora sparar varje version av en anteckning när valvmappen är ett git-repo. Kör {cmd} i valvmappen en gång (se Konfiguration, ”Versionshistorik” i dokumentationen); därefter sparas varje ändring här.",
  "Memora keeps it in one place:": "Memora håller den på ett ställe:",
  "Memora saves every note as a plain Markdown file on the machine it runs on. Nothing is locked in: open the files in any editor, back them up, or keep them in Git.": "Memora sparar varje anteckning som en vanlig Markdown-fil på maskinen den körs på. Inget är inlåst: öppna filerna i vilken redigerare som helst, säkerhetskopiera dem eller förvara dem i Git.",
  "Memora speaks MCP over streamable HTTP. Apps send the key in the header <code>Authorization: Bearer &lt;key&gt;</code>.": "Memora talar MCP över streamable HTTP. Appar skickar nyckeln i rubriken <code>Authorization: Bearer &lt;key&gt;</code>.",
  "Memora stops on the machine it runs on. Your notes stay safe on disk.": "Memora stannar på maskinen den körs på. Dina anteckningar är säkra på disken.",
  "Memora version": "Memora-version",
  "Memora v{latest} is available. This server runs v{current}.": "Memora v{latest} finns. Den här servern kör v{current}.",
  "Memora, open Overview": "Memora, öppna Översikt",
  "Memora: a notes vault you host yourself, with an agent that tidies it.": "Memora: ett anteckningsvalv du själv hostar, med en agent som städar det.",
  "Memory used: {used} of {win}": "Minne som används: {used} av {win}",
