  "Messaged {agent}": "Skrev till {agent}",
  "Messages and the message box line up exactly in every width, the model picker has its own surface, the fleeting chat fits phones, and a question's options never slide away as you tap them.": "Meddelanden och meddelandefältet linjerar exakt i alla bredder, modellväljaren har en egen yta, den flyktiga chatten får plats på telefonen och en frågas alternativ glider inte undan när du trycker.",
  "Middle-drag": "Mittendragning",
  "Midnight": "Midnatt",
  "Minimap": "Minikarta",
  "Minimap: click or drag to move the view": "Minikarta: klicka eller dra för att flytta vyn",
  "Mist": "Dimma",
  "Mnemo (AI agent)": "Mnemo (AI-agent)",
  "Mnemo button hidden. Show it again from More, Show the Mnemo button.": "Mnemo-knappen är dold. Visa den igen via Mer, Visa Mnemo-knappen.",
  "Mnemo goes on without sub-agents": "Mnemo fortsätter utan underagenter",
  "Mnemo has no model yet: add a provider and its models in Settings, Mnemo": "Mnemo har ingen modell än: lägg till en leverantör och dess modeller i Inställningar, Mnemo",
  "Mnemo is built into Memora. Connect your own AI key, then ask in plain words: it finds, writes, tags, links and tidies notes for you.": "Mnemo är inbyggd i Memora. Anslut din egen AI-nyckel och fråga sedan med vanliga ord: den hittar, skriver, taggar, länkar och städar anteckningar åt dig.",
  "Mnemo is still answering in this chat": "Mnemo svarar fortfarande i den här chatten",
  "Mnemo is the agent built into Memora. Connect your own AI key and ask in plain words: it keeps your notes in order while your other apps use them.": "Mnemo är agenten som är inbyggd i Memora. Anslut din egen AI-nyckel och fråga med vanliga ord: den håller ordning på dina anteckningar medan dina andra appar använder dem.",
  "Mnemo keeps at most {n} providers; delete one first": "Mnemo behåller högst {n} leverantörer; ta bort en först",
  "Mnemo manages its sub-agents, keeps its plan with the chat, and the chat fits every screen better.": "Mnemo hanterar sina underagenter, håller sin plan i chatten, och chatten passar bättre på varje skärm.",
  "Mnemo runs its sub-agents": "Mnemo styr sina underagenter",
  "Mnemo stopped after {n} steps; say \"continue\" to go on.": "Mnemo stannade efter {n} steg; skriv ”fortsätt” för att gå vidare.",
  "Mnemo's plan, live": "Mnemos plan, live",
  "Mnemo's question sits on its own band, its answers below as rows to tap, as many as the question needs.": "Frågan från Mnemo står på ett eget band, svaren under som rader att trycka på, så många som frågan behöver.",
  "Mnemo, trash and settings": "Mnemo, papperskorg och inställningar",
  "Mnemo, your notes agent": "Mnemo, din anteckningsagent",
