  "Not created yet. Click to create it.": "Inte skapad än. Klicka för att skapa den.",
  "Not done: Mnemo is in Ask first mode, so changes wait for the owner's OK. Ask with ask_owner (say what you will change; give an option with approve: true such as \"Yes, go ahead\"), then make the change after they approve.": "Inte gjort: Mnemo är i läget Fråga först, så ändringar väntar på ägarens OK. Fråga med ask_owner (säg vad du ska ändra; ge ett alternativ med approve: true som ”Ja, kör på”) och gör sedan ändringen när ägaren godkänner.",
  "Not done: Mnemo is in Read only mode, so notes are not changed. Say what you would change; the owner can switch to Ask first or Auto in the chat.": "Inte gjort: Mnemo är i läget Endast läsning, så anteckningar ändras inte. Säg vad du skulle ändra; ägaren kan byta till Fråga först eller Auto i chatten.",
  "Not done: the chat is in Ask first mode, so a sub-agent cannot change notes. Say in your answer what should change; Mnemo asks the owner.": "Inte gjort: chatten är i läget Fråga först, så en underagent kan inte ändra anteckningar. Säg i ditt svar vad som bör ändras; Mnemo frågar ägaren.",
  "Not done: the owner switched {tool} off for Mnemo (Settings, Mnemo).": "Inte gjort: ägaren stängde av {tool} för Mnemo (Inställningar, Mnemo).",
