  "Notes and images in the notes folder.": "Anteckningar och bilder i anteckningsmappen.",
  "Notes and the links between them show up here as a map. The guide shows how to have an AI save its knowledge here, or write a note yourself.": "Anteckningar och länkarna mellan dem visas här som en karta. Guiden visar hur du låter en AI spara sin kunskap här, eller skriver en anteckning själv.",
  "Notes appear as the AI saves them and light up the brain. This page turns into your dashboard when the first note arrives.": "Anteckningar dyker upp när AI:n sparar dem och lyser upp hjärnan. Den här sidan blir din översikt när den första anteckningen kommer.",
