  "Nothing in note names, folders or text, and nothing spelled close to it. Try fewer letters, another spelling, or a word from inside a note.": "Inget i anteckningsnamn, mappar eller text, och inget stavat nära det. Försök med färre bokstäver, en annan stavning eller ett ord från en anteckning.",
