  "Older Gemini CLI without <code>gemini mcp add</code>: add the server to <code>~/.gemini/settings.json</code> under <code>mcpServers</code>, with <code>httpUrl</code> and the same header.": "Äldre Gemini CLI utan <code>gemini mcp add</code>: lägg till servern i <code>~/.gemini/settings.json</code> under <code>mcpServers</code>, med <code>httpUrl</code> och samma rubrik.",
  "Older changes stay in History.": "Äldre ändringar finns kvar i Historik.",
  "Older messages were left out to fit the model's context.": "Äldre meddelanden utelämnades för att rymmas i modellens kontext.",
