  "Older versions of a note: read, compare, restore, and the trash.": "Äldre versioner av en anteckning: läs, jämför, återställ, och papperskorgen.",
  "Oldest entry": "Äldsta post",
  "On": "På",
  "On desktop, drag the edge of the chat list or the side panel to make it wider or narrower. Each keeps a minimum and remembers its width.": "På datorn drar du i kanten av chattlistan eller sidopanelen för att göra den bredare eller smalare. Var och en har en minsta bredd och minns sin bredd.",
  "On its avatar, its sparks in the brain and every activity row.": "På dess avatar, dess gnistor i hjärnan och varje aktivitetsrad.",
  "On this page": "På den här sidan",
  "On: tap to switch off": "På: tryck för att slå av",
  "On: {mnemo} notes what it picks up in chats. Off: only what you add here. Saved at once.": "På: {mnemo} noterar vad den fångar upp i chattar. Av: bara det du lägger till här. Sparas direkt.",
  "Once installed, the app has its own icon, opens full screen and stays reachable when the network drops.": "När appen är installerad får den en egen ikon, öppnas i helskärm och går att nå även när nätverket försvinner.",
  "Once it is connected, paste this into a new chat in that app. It tells the AI to store what it knows into Memora.": "När den är ansluten, klistra in detta i en ny chatt i den appen. Det säger åt AI:n att lagra det den vet i Memora.",
  "Once its app is set up, every call shows up here as it happens.": "När dess app är installerad visas varje anrop här när det sker.",
  "Once {name} is connected, everything it reads, writes and searches shows up here, live.": "När {name} är ansluten visas allt den läser, skriver och söker här, live.",
  "One address": "En adress",
  "One agent per app or device: its own key, its own name in Activity, turned off on its own.": "En agent per app eller enhet: egen nyckel, eget namn i Aktivitet, avstängd för sig.",
  "One click": "Ett klick",
  "One device or connection, such as 203.0.113.7. Searching \"what is my IP\" shows yours.": "En enhet eller anslutning, som 203.0.113.7. Sök ”what is my IP” för att se din.",
  "One device or connection.": "En enhet eller anslutning.",
  "One folder of notes that you and every connected AI share.": "En mapp med anteckningar som du och varje ansluten AI delar",
  "One is hidden by the folder rule.": "En är dold av mappregeln.",
  "One key per agent, its own permissions.": "En nyckel per agent, egna behörigheter.",
  "One last step": "Ett sista steg",
  "One memory every agent reads and writes, and you can see, edit and connect all of it.": "Ett minne som varje agent läser och skriver, och du kan se, redigera och koppla allt.",
  "One memory for every AI": "Ett minne för varje AI",
  "One note shows this image; it will show as missing there. The version history keeps it.": "En anteckning visar den här bilden; den visas som saknad där. Versionshistoriken behåller den.",
  "One per line. They show among the suggestions on a new chat, marked Yours, and stay until you change them.": "En per rad. De visas bland förslagen i en ny chatt, markerade Dina, och finns kvar tills du ändrar dem.",
  "One private memory that you and your AI apps share, so nothing has to be explained twice.": "Ett privat minne som du och dina AI-appar delar, så att inget behöver förklaras två gånger.",
  "One set of notes for every AI app": "En uppsättning anteckningar för varje AI-app",
  "Online": "Online",
  "Only PNG, JPEG, WebP and GIF images can be added": "Bara PNG-, JPEG-, WebP- och GIF-bilder kan läggas till",
  "Only in the current version": "Bara i den aktuella versionen",
  "Only in version {n}": "Bara i version {n}",
  "Only letters, digits and - _ / . can be used.": "Bara bokstäver, siffror och - _ / . kan användas.",
  "Only looks at notes; changes nothing.": "Tittar bara på anteckningar; ändrar ingenting.",
  "Only looks things up and never writes. For agents with a read-only key.": "Slår bara upp och skriver aldrig. För agenter med en skrivskyddad nyckel.",
  "Only pictures in your newest message go to the image model, and you hear of it in a short toast.": "Bara bilder i ditt senaste meddelande går till bildmodellen, och du får veta det i en kort avisering.",
  "Only reads and answers; never changes notes": "Läser och svarar bara; ändrar aldrig anteckningar",
  "Only the agents you pick. New agents can’t see it.": "Bara de agenter du väljer. Nya agenter kan inte se den.",
  "Only the first rule that fits a request counts.": "Bara den första regeln som passar en förfrågan räknas.",
  "Only the latest questions go on the page at first; earlier ones come in as you scroll up or jump to them on the timeline.": "Först visas bara de senaste frågorna; äldre kommer när du rullar uppåt eller hoppar till dem på tidslinjen.",
