  "Save into Memora what I've shared with you about my personal life: my interests, habits, goals, the people who matter to me and things I care about. Put these notes in a folder named Private, one note per topic, and link related notes. Never save passwords, card numbers or other secrets. When you're done, tell me what you saved.": "Spara i Memora vad jag har delat med dig om mitt privatliv: mina intressen, vanor, mål, de som betyder något för mig och saker jag bryr mig om. Lägg anteckningarna i en mapp som heter Private, en anteckning per ämne, och länka relaterade anteckningar. Spara aldrig lösenord, kortnummer eller andra hemligheter. När du är klar, berätta vad du sparade.",
  "Save into Memora what you know about my work: my role, my team, the projects I'm on and where they stand, and decisions we made. Make one note per project or topic and link them together.": "Spara i Memora vad du vet om mitt arbete: min roll, mitt team, projekten jag är med i och hur de ligger till, samt beslut vi fattat. Gör en anteckning per projekt eller ämne och länka ihop dem.",
