  "This address would be locked out.": "Den här adressen skulle bli utelåst.",
  "This can no longer be undone: the note has changed since.": "Det här kan inte längre ångras: anteckningen har ändrats sedan dess.",
  "This chat": "Den här chatten",
  "This chat keeps everything from its first message to the last for this model. Near {n} tokens {mnemo} folds the older messages into a summary and carries on.": "Den här chatten behåller allt från sitt första meddelande till det sista för den här modellen. Vid {n} tokens vecklar {mnemo} ihop de äldre meddelandena till en sammanfattning och fortsätter.",
  "This chat so far was answered by {prev}. From the next message on, {model} answers, with the whole chat as context. Its answers may read a little differently, and its memory for this chat may be smaller or larger.": "Den här chatten har hittills besvarats av {prev}. Från nästa meddelande svarar {model}, med hela chatten som kontext. Dess svar kan låta lite annorlunda, och dess minne för den här chatten kan vara mindre eller större.",
  "This chat so far was answered by {prev}. From the next message on, {model} answers, with the whole chat as context. Its answers may read a little differently.": "Den här chatten har hittills besvarats av {prev}. Från nästa meddelande svarar {model}, med hela chatten som kontext. Dess svar kan låta lite annorlunda.",
