  "{mnemo} asks this model when you want a picture made.": "{mnemo} ber den här modellen när du vill ha en bild gjord.",
  "{mnemo} button hidden. Bring it back from More, Show the {mnemo} button.": "Knappen {mnemo} är dold. Ta tillbaka den under Mer, Visa knappen {mnemo}.",
  "{mnemo} button hidden. Show it again here or from More.": "Knappen {mnemo} är dold. Visa den igen här eller under Mer.",
  "{mnemo} could not write new ones just now. Check the model in Settings.": "{mnemo} kunde inte skriva nya just nu. Kontrollera modellen i Inställningar.",
  "{mnemo} hands pictures to this model when the chat model cannot see.": "{mnemo} ger bilder till den här modellen när chattmodellen inte kan se.",
