  "{mnemo} looks after your notes": "{mnemo} tar hand om dina anteckningar",
  "{mnemo} may learn about you": "{mnemo} får lära sig om dig",
  "{mnemo} only works in your notes. Each change shows in Activity and can be undone from History.": "{mnemo} arbetar bara i dina anteckningar. Varje ändring visas i Aktivitet och kan ångras från Historik.",
  "{mnemo} reads your vault in a new chat and keeps what it learns here.": "{mnemo} läser ditt valv i en ny chatt och behåller det den lär sig här.",
  "{mnemo} settings saved": "{mnemo}-inställningarna sparades",
  "{mnemo} settings: models and keys": "{mnemo}-inställningar: modeller och nycklar",
  "{mnemo} starts sub-agents by itself when a task splits well; there is nothing to set up. They run on your default model, then the fallbacks, unless you name a model in the chat. Follow them, and switch their model, in Agents at the top right of the chat. They use tokens of their own, so in Ask first {mnemo} asks and says roughly how many; in Auto they just run. Saved at once.": "{mnemo} startar underagenter själv när en uppgift delar upp sig bra; inget behöver ställas in. De körs på din standardmodell, sedan reservmodellerna, om du inte anger en modell i chatten. Följ dem och byt deras modell under Agenter uppe till höger i chatten. De använder egna tokens, så i Fråga först frågar {mnemo} och säger ungefär hur många; i Auto körs de bara. Sparas direkt.",
  "{mnemo} stopped it": "{mnemo} stoppade den",
  "{mnemo} will keep that in mind": "{mnemo} kommer ihåg det",
  "{mnemo} writes new suggestions from your recent notes (yours stay)": "{mnemo} skriver nya förslag utifrån dina senaste anteckningar (dina finns kvar)",
  "{mnemo}'s own ({n})": "{mnemo}s egna ({n})",
  "{mnemo}'s own notes on how to talk to you, read in every chat. Click one to change it.": "{mnemo}s egna anteckningar om hur den pratar med dig, lästa i varje chatt. Klicka på en för att ändra den.",
  "{mnemo}, your notes agent": "{mnemo}, din anteckningsagent",
  "{mnemo}: {text}": "{mnemo}: {text}",
  "{model} cannot look at images; it got their names instead. Set a model that reads images in Settings to have them seen.": "{model} kan inte titta på bilder; den fick deras namn i stället. Ange en modell som läser bilder i Inställningar för att de ska ses.",
  "{model} cannot look at images; the image model described them for it.": "{model} kan inte titta på bilder; bildmodellen beskrev dem åt den.",
  "{model} cannot read pictures, so it only gets their names. Set a model that reads images, or switch this chat's model.": "{model} kan inte läsa bilder, så den får bara deras namn. Ange en modell som läser bilder, eller byt chattens modell.",
  "{model} cannot read pictures, so it only got their names. Set a model that reads images, or switch this chat's model.": "{model} kan inte läsa bilder, så den fick bara deras namn. Ange en modell som läser bilder, eller byt chattens modell.",
  "{model} cannot read pictures, so the image model looked at them for it.": "{model} kan inte läsa bilder, så bildmodellen tittade på dem åt den.",
  "{model} cannot read pictures, so the image model looks at them for it.": "{model} kan inte läsa bilder, så bildmodellen tittar på dem åt den.",
  "{model} did not answer ({why}); trying again in {wait} s ({n}/{total})…": "{model} svarade inte ({why}); försöker igen om {wait} s ({n}/{total})…",
